"""Bounded timing probe; measures instrumented calls, not a latency benchmark."""
import hashlib,heapq,importlib.util,json,resource,sys,time
from pathlib import Path
import wholebodyx.dynamics as dynamics
root=Path('/home/ubuntu/workspace/chase/WholeBodyX')
spec=importlib.util.spec_from_file_location('stage_demo',root/'examples/python/h1_dynamics_wbc.py'); demo=importlib.util.module_from_spec(spec); spec.loader.exec_module(demo)
active=False; depth=0; stages={}; cpu_top=[]; wall_top=[]; aggregate={}

def measured(name,method):
 def call(*args,**kwargs):
  global depth
  if not active or depth: return method(*args,**kwargs)
  depth+=1; cpu=time.thread_time(); wall=time.perf_counter()
  try: return method(*args,**kwargs)
  finally:
   w=(time.perf_counter()-wall)*1000; c=(time.thread_time()-cpu)*1000; depth-=1
   for bucket in (stages,aggregate):
    row=bucket.setdefault(name,{'calls':0,'thread_ms':0.,'wall_ms':0.}); row['calls']+=1; row['thread_ms']+=c; row['wall_ms']+=w
 return call

original_factory=dynamics.osqp.OSQP

def factory(*args,**kwargs):
 solver=original_factory(*args,**kwargs)
 for name in ('setup','update','update_settings','warm_start','solve'):
  setattr(solver,name,measured('osqp_'+name,getattr(solver,name)))
 return solver

class ProbeWBC(dynamics.ContactWBC):
 def formulate(self,*args,**kwargs):
  return measured('formulate',super().formulate)(*args,**kwargs)
 def solve(self,*args,**kwargs):
  global active,stages
  stages={}; active=True; cpu=time.thread_time(); wall=time.perf_counter(); result=None
  try:
   result=super().solve(*args,**kwargs); return result
  finally:
   w=(time.perf_counter()-wall)*1000; c=(time.thread_time()-cpu)*1000; active=False
   index=report['samples']+1; report['samples']=index
   report['thread_total_ms']+=c; report['wall_total_ms']+=w
   payload={'sample':index,'thread_ms':c,'wall_ms':w,'iterations':None if result is None else result['iterations'],'stages':stages,'unattributed_thread_ms':c-sum(x['thread_ms'] for x in stages.values())}
   for heap,value in ((cpu_top,c),(wall_top,w)):
    entry=(value,index,payload)
    if len(heap)<10: heapq.heappush(heap,entry)
    elif value>heap[0][0]: heapq.heapreplace(heap,entry)

report={'status':'running','steps':320000,'samples':0,'thread_total_ms':0.,'wall_total_ms':0.,'scope':'Exclusive top-level phase timers inside WBC; CPU/wall overhead is included. This is an attribution probe, not an uninstrumented performance benchmark.','source_sha256':{p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in ('python/wholebodyx/dynamics.py','python/wholebodyx/centroidal.py','python/wholebodyx/qp.py','examples/python/h1_dynamics_wbc.py')},'probe_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
dynamics.osqp.OSQP=factory; demo.ContactWBC=ProbeWBC
s=demo.DynamicsDemo(controller='mpc',amplitude=.05,push_force=3.)
started=heartbeat=time.monotonic()
try:
 for index in range(report['steps']):
  s.step()
  if time.monotonic()-heartbeat>=30:
   heartbeat=time.monotonic(); print(json.dumps({'steps':index+1,'wall_s':heartbeat-started,'max_thread_ms':cpu_top[-1][0] if cpu_top else 0.}),flush=True)
 assert report['samples']==report['steps']
 assert aggregate['formulate']['calls']==report['steps']
 assert aggregate['osqp_solve']['calls']==report['steps']+s.controller.solver_recoveries
 report['status']='passed'
except BaseException as exc:
 report['status']='failed';report['error']=f'{type(exc).__name__}: {exc}';raise
finally:
 dynamics.osqp.OSQP=original_factory
 report.update(wall_s=time.monotonic()-started,aggregate_stages=aggregate,slowest_cpu=[x[2] for x in sorted(cpu_top,reverse=True)],slowest_wall=[x[2] for x in sorted(wall_top,reverse=True)],solver_setups=s.controller.solver_setups,solver_recoveries=s.controller.solver_recoveries,max_contact_position_error_m=s.max_contact_error,peak_rss_kib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
 Path('/tmp/wholebodyx-20261020-stage-probe.json').write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
 print(json.dumps({k:v for k,v in report.items() if not k.startswith('slowest')},indent=2),flush=True)

