"""Compare ADMM relaxation using unchanged tolerance and physical acceptance."""
import hashlib,importlib.util,json,sys,time
from pathlib import Path
import numpy as np
import wholebodyx.dynamics as current
root=Path('/home/ubuntu/workspace/chase/WholeBodyX')
def module(name,path):
 spec=importlib.util.spec_from_file_location(name,path); m=importlib.util.module_from_spec(spec);sys.modules[name]=m;spec.loader.exec_module(m);return m
implementations={'1.6':current}
for value in ('1.7','1.8','1.9'):implementations[value]=module('wholebodyx._alpha_'+value.replace('.','_'),'/tmp/wholebodyx-20261020-alpha'+value+'.py')
demo=module('alpha_comparison_demo',root/'examples/python/h1_dynamics_wbc.py')
report={'status':'running','steps_per_trial':6400,'repeats':4,'results':[],'differences':[],'source_sha256':{name:hashlib.sha256(Path(m.__file__).read_bytes()).hexdigest() for name,m in implementations.items()},'scope':'Instrumented whole-WBC CPU and wall clocks, alternating implementation order. All eps/max_iter/rho/polishing and physical acceptance thresholds are unchanged.'}
output=Path('/tmp/wholebodyx-20261020-alpha-comparison.json')
for mode in ('wbc','mpc'):
 for repeat in range(4):
  traces={}
  for alpha in (list(implementations) if repeat%2==0 else list(reversed(implementations))):
   impl=implementations[alpha];cpu=[];wall=[];iterations=[];trace=[];max_violation=0.;error=None
   class Measured(impl.ContactWBC):
    def solve(self,*args,**kwargs):
     c=time.thread_time();w=time.perf_counter();result=super().solve(*args,**kwargs)
     cpu.append((time.thread_time()-c)*1000);wall.append((time.perf_counter()-w)*1000);iterations.append(result['iterations']);return result
   demo.FloatingBaseDynamics=impl.FloatingBaseDynamics;demo.ContactWBC=Measured
   s=demo.DynamicsDemo(controller=mode,amplitude=.05,push_force=3.)
   try:
    for step in range(6400):
     row=s.step();max_violation=max(max_violation,row['constraint_violation'])
     trace.append(np.r_[s.controller.previous[s.robot.nv:s.robot.nv+s.robot.na],s.state.q])
   except Exception as exc:error=f'{type(exc).__name__}: {exc}'
   r={'controller':mode,'repeat':repeat,'alpha':alpha,'status':'failed' if error else 'passed','steps':len(trace),'solver_setups':s.controller.solver_setups,'solver_recoveries':s.controller.solver_recoveries,'max_constraint_violation':max_violation,'max_contact_position_error_m':s.max_contact_error,'max_dynamics_residual':s.max_dynamics_residual}
   if error:r['error']=error
   if cpu:
    r.update(mean_cpu_ms=float(np.mean(cpu)),p95_cpu_ms=float(np.percentile(cpu,95)),p99_cpu_ms=float(np.percentile(cpu,99)),max_cpu_ms=max(cpu),mean_wall_ms=float(np.mean(wall)),p99_wall_ms=float(np.percentile(wall,99)),max_wall_ms=max(wall),total_iterations=int(sum(iterations)),p99_iterations=float(np.percentile(iterations,99)),max_iterations=max(iterations))
   report['results'].append(r);traces[alpha]=None if error else np.asarray(trace)
   print(json.dumps(r),flush=True);output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
  for alpha in ('1.7','1.8','1.9'):
   if traces['1.6'] is not None and traces[alpha] is not None:
    difference=np.max(np.abs(traces['1.6']-traces[alpha]),axis=0)
    report['differences'].append({'controller':mode,'repeat':repeat,'alpha':alpha,'max_torque_difference_nm':float(np.max(difference[:19])),'max_configuration_difference':float(np.max(difference[19:]))})
  output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
report['status']='completed';output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')

