import heapq,json,resource,time
from pathlib import Path
output=Path('/tmp/wholebodyx-20261020-wall-monitor.json')
started=time.monotonic(); previous=started; unix=time.time(); slow=[]; count=0
report={'status':'running','interval_s':.5,'clock_scope':'independent validation process; gaps do not identify a scheduling or suspension cause'}
try:
 while time.monotonic()<1792440661- (time.time()-time.monotonic())-300:
  time.sleep(.5); now=time.monotonic(); stamp=time.time(); gap=now-previous; count+=1
  sample=(gap,count,unix,stamp)
  if len(slow)<20: heapq.heappush(slow,sample)
  elif gap>slow[0][0]: heapq.heapreplace(slow,sample)
  previous=now; unix=stamp
 report['status']='passed'
finally:
 report.update(wall_s=time.monotonic()-started,samples=count,slowest_gaps=[dict(gap_s=x[0],sample=x[1],unix_start_s=x[2],unix_end_s=x[3]) for x in sorted(slow,reverse=True)])
 output.write_text(json.dumps(report,indent=2)+'\n')
